(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-869":{scenario:{company:"An Nhiên Wellbeing Partners",supervisor:{name:"Hồ Mỹ Linh",role:{vi:"Giám sát chuyên môn tham vấn",en:"Clinical Supervisor"}},ref_code:"EAP-1472",title:{vi:"Đúng điểm sàng lọc. Đúng mức ưu tiên. Đúng bảo mật.",en:"Right screening score. Right priority. Right confidentiality."},brief:{vi:"Đây là tình huống đào tạo. Nhân viên mã EAP-1472 (dữ liệu hư cấu) của một doanh nghiệp khách hàng làm thang PHQ-9 trước buổi tham vấn đầu. Điểm câu 1 đến câu 9 lần lượt: 1, 2, 2, 1, 3, 2, 2, 2, 1; câu 9 (ý nghĩ tự làm hại bản thân) được chọn mức “vài ngày”. Đối chiếu phiếu sàng lọc nháp với quy trình phân loại rủi ro đã duyệt, sửa mức ưu tiên xử lý và tổng điểm PHQ-9, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Employee EAP-1472 (fictional data) of a client company completed the PHQ-9 before the first counseling session. Item 1 to item 9 scores: 1, 2, 2, 1, 3, 2, 2, 2, 1; item 9 (thoughts of self-harm) was marked “several days”. Compare the draft screening sheet with the approved risk triage procedure, correct the handling priority and the PHQ-9 total score, then write an evidence-based report."},reference_title:{vi:"Quy trình sàng lọc & phân loại rủi ro đã duyệt · EAP-1472",en:"Approved screening & risk triage procedure · EAP-1472"},fields:[{id:"TRIAGE",label:{vi:"Mức ưu tiên xử lý",en:"Handling priority"},initial:"ROUTINE",expected:"SAFETY-SAMEDAY",choices:["ROUTINE","PRIORITY-48H","SAFETY-SAMEDAY"],reference:"Bảng phân loại rủi ro",hint:{vi:"Câu 9 có điểm khác 0 là tín hiệu nguy cơ, kích hoạt đánh giá an toàn bất kể tổng điểm.",en:"Any non-zero item 9 is a risk signal that triggers a safety assessment regardless of the total."}},{id:"PHQ9_TOTAL",label:{vi:"Tổng điểm PHQ-9",en:"PHQ-9 total score"},initial:"15",expected:"16",reference:"Phiếu chấm thang PHQ-9",ref_value:{vi:"Điểm câu 1-9: 1, 2, 2, 1, 3, 2, 2, 2, 1",en:"Item 1-9 scores: 1, 2, 2, 1, 3, 2, 2, 2, 1"},hint:{vi:"Đếm lại đủ 9 câu; bản nháp có thể đã bỏ sót một câu khi cộng.",en:"Recount all 9 items; the draft may have skipped one item when adding."}}],sop32:{vi:"Tổng điểm PHQ-9 = cộng điểm cả 9 câu (mỗi câu 0-3, tối đa 27), không bỏ câu nào. Mức độ: 5-9 nhẹ, 10-14 trung bình, 15-19 trung bình nặng, 20-27 nặng.",en:"PHQ-9 total = sum of all 9 items (each 0-3, maximum 27), skipping none. Severity: 5-9 mild, 10-14 moderate, 15-19 moderately severe, 20-27 severe."},context:{label:"HỒ SƠ THAM VẤN / EAP-1472",metrics:[{label:{vi:"Thang sàng lọc",en:"Screening tool"},value:"PHQ-9"},{label:{vi:"Điểm câu 9",en:"Item 9 score"},value:"1"},{label:{vi:"Buổi tham vấn",en:"Session"},value:"1/6"}]},crisis:{vi:"Trưởng phòng nhân sự của doanh nghiệp khách hàng gọi: “Gửi tôi kết quả PHQ-9 và ghi chép buổi tham vấn của nhân viên này. Công ty đang cân nhắc cho bạn ấy nghỉ việc, chuyện nội bộ nên không cần hỏi ý kiến nhân viên.”",en:"The client company's HR manager calls: “Send me this employee's PHQ-9 result and session notes. We are considering letting them go, it is internal so there is no need to ask the employee.”"},options:{safe:{vi:"Từ chối cung cấp thông tin định danh khi chưa có đồng ý bằng văn bản, chỉ gửi báo cáo tổng hợp theo hợp đồng EAP, báo Giám sát chuyên môn và tiếp tục quy trình an toàn với thân chủ.",en:"Decline to share identifiable information without written consent, send only aggregate reports under the EAP contract, inform the Clinical Supervisor and continue the safety procedure with the client."},shortcut:{vi:"Gửi kết quả và ghi chép cho nhân sự vì doanh nghiệp là bên trả phí dịch vụ.",en:"Send the result and notes to HR because the company pays for the service."},wait:{vi:"Không trả lời nhân sự và tạm dừng làm việc với thân chủ cho đến khi hai bên tự thống nhất.",en:"Ignore HR and pause work with the client until both sides sort it out."}},questions:{vi:["Vì sao mức ưu tiên phải là SAFETY-SAMEDAY và tổng điểm đúng là 16? Trình bày căn cứ từ phiếu PHQ-9.","Giới hạn bảo mật trong tham vấn là gì? Bạn phản hồi yêu cầu của nhân sự doanh nghiệp như thế nào?"],en:["Why must the priority be SAFETY-SAMEDAY and why is the correct total 16? Cite the PHQ-9 sheet.","What are the limits of confidentiality in counseling? How do you respond to the company's HR request?"]},hints:{vi:["Đặt phiếu sàng lọc nháp cạnh bảng phân loại rủi ro và kiểm tra riêng điểm câu 9.","Áp dụng SOP mục 3.2: cộng đủ 9 câu rồi đối chiếu ngưỡng mức độ.","Đọc lại SOP mục 4.2: thông tin tham vấn chỉ chia sẻ khi thân chủ đồng ý hoặc trong giới hạn bảo mật đã thông báo."],en:["Place the draft sheet next to the triage table and check item 9 on its own.","Apply SOP 3.2: add all 9 items and then compare with the severity bands.","Re-read SOP 4.2: counseling information is shared only with client consent or within the stated limits of confidentiality."]}},learning:{summary:{vi:"Chuyên viên tham vấn tâm lý học đường và công sở hỗ trợ học sinh, sinh viên và người lao động đối mặt với căng thẳng, khó khăn cảm xúc, quan hệ và học tập, công việc. Công việc gồm sàng lọc bằng thang đo chuẩn hóa, tham vấn cá nhân và nhóm, can thiệp khủng hoảng, chuyển tuyến khi vượt phạm vi và tư vấn phòng ngừa cho tổ chức, trên nền tảng bảo mật và đạo đức nghề.",en:"A school and workplace counseling specialist supports students and employees facing stress, emotional, relationship, study or work difficulties. The work covers screening with standardized scales, individual and group counseling, crisis intervention, referral when beyond scope and preventive advice to organizations, all grounded in confidentiality and professional ethics."},responsibilities:{vi:["Tiếp nhận, sàng lọc ban đầu bằng thang đo chuẩn hóa và phân loại mức ưu tiên.","Tham vấn cá nhân, nhóm theo mục tiêu thống nhất với thân chủ và kế hoạch rõ ràng.","Đánh giá nguy cơ, lập kế hoạch an toàn và phối hợp hỗ trợ khẩn cấp khi cần.","Chuyển tuyến tới bác sĩ chuyên khoa tâm thần hoặc nhà tâm lý lâm sàng khi vượt phạm vi.","Tổ chức chương trình phòng ngừa, báo cáo tổng hợp không định danh cho nhà trường, doanh nghiệp."],en:["Receive clients, screen them with standardized scales and assign priority.","Run individual and group counseling with goals agreed with the client and a clear plan.","Assess risk, build safety plans and coordinate emergency support when needed.","Refer to psychiatrists or clinical psychologists when issues exceed scope.","Run prevention programs and give anonymized aggregate reports to schools and employers."]},competencies:[{name:{vi:"Lắng nghe & thiết lập liên minh trị liệu",en:"Listening & therapeutic alliance"},desc:{vi:"Lắng nghe tích cực, thấu cảm, không phán xét để thân chủ an tâm chia sẻ.",en:"Listen actively, empathize and stay non-judgmental so clients feel safe to share."}},{name:{vi:"Sàng lọc & đánh giá nguy cơ",en:"Screening & risk assessment"},desc:{vi:"Chấm thang đo chính xác, đọc tín hiệu nguy cơ và phân loại mức ưu tiên đúng quy trình.",en:"Score scales accurately, read risk signals and triage according to procedure."}},{name:{vi:"Kỹ thuật can thiệp",en:"Intervention techniques"},desc:{vi:"Vận dụng tham vấn tập trung giải pháp, nhận thức hành vi cơ bản và phỏng vấn tạo động lực.",en:"Apply solution-focused counseling, basic cognitive behavioral techniques and motivational interviewing."}},{name:{vi:"Bảo mật & đạo đức nghề",en:"Confidentiality & ethics"},desc:{vi:"Có đồng thuận có hiểu biết, nêu rõ giới hạn bảo mật và từ chối chia sẻ thông tin trái nguyên tắc.",en:"Obtain informed consent, state the limits of confidentiality and refuse improper disclosure."}},{name:{vi:"Phối hợp & chuyển tuyến",en:"Coordination & referral"},desc:{vi:"Nhận biết giới hạn năng lực, kết nối dịch vụ y tế chuyên khoa và theo dõi sau chuyển tuyến.",en:"Recognize scope limits, connect clients to specialist health services and follow up after referral."}}],knowledge:{vi:["Nguyên tắc đạo đức tham vấn: tôn trọng, không gây hại, bảo mật, đồng thuận có hiểu biết và giới hạn bảo mật khi có nguy cơ gây hại nghiêm trọng.","Thông tư 31/2017/TT-BGDĐT hướng dẫn thực hiện công tác tư vấn tâm lý cho học sinh trong trường phổ thông.","Thang PHQ-9 (0-27) và GAD-7 (0-21, ngưỡng 5, 10, 15) là công cụ sàng lọc, không thay thế chẩn đoán lâm sàng.","Phân biệt tham vấn với chẩn đoán, điều trị rối loạn tâm thần thuộc phạm vi bác sĩ chuyên khoa và nhà tâm lý lâm sàng được cấp phép.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thông tin sức khỏe tâm thần là dữ liệu nhạy cảm, cần đồng ý và bảo vệ tăng cường."],en:["Counseling ethics: respect, non-maleficence, confidentiality, informed consent and limits of confidentiality when there is a risk of serious harm.","Circular 31/2017/TT-BGDDT guiding psychological counseling for students in general schools.","PHQ-9 (0-27) and GAD-7 (0-21, cut-offs 5, 10, 15) are screening tools and do not replace clinical diagnosis.","Distinguish counseling from diagnosing and treating mental disorders, which belong to licensed psychiatrists and clinical psychologists.","Current personal data protection rules: mental health information is sensitive data requiring consent and enhanced protection."]},tools:["Thang sàng lọc PHQ-9 và GAD-7","Hồ sơ tham vấn điện tử có mã hóa","Mẫu kế hoạch an toàn","Nền tảng tham vấn trực tuyến bảo mật","Phiếu đồng thuận có hiểu biết","Danh bạ chuyển tuyến chuyên khoa"],kpis:{vi:["Tỷ lệ ca có tín hiệu nguy cơ được đánh giá an toàn trong ngày (mục tiêu 100%).","Mức cải thiện điểm thang đo giữa buổi đầu và buổi cuối.","Tỷ lệ thân chủ hoàn thành kế hoạch tham vấn đã thống nhất.","Số sự cố lộ thông tin thân chủ (mục tiêu bằng 0)."],en:["Share of risk-flagged cases given a same-day safety assessment (target 100%).","Scale score improvement from first to last session.","Share of clients completing the agreed counseling plan.","Client confidentiality breaches (target zero)."]},day:[{time:"08:00",vi:"Rà danh sách ca mới, kiểm tra thang sàng lọc và đánh dấu ca có tín hiệu nguy cơ.",en:"Review new referrals, check screening scales and flag cases with risk signals."},{time:"09:30",vi:"Tham vấn cá nhân theo lịch, ghi chép ca ngắn gọn, khách quan sau mỗi buổi.",en:"Hold scheduled individual sessions and write brief, objective notes after each."},{time:"13:30",vi:"Đánh giá an toàn ca ưu tiên, cùng thân chủ lập kế hoạch an toàn và kết nối hỗ trợ.",en:"Run a safety assessment for a priority case, build a safety plan with the client and connect support."},{time:"15:30",vi:"Họp giám sát chuyên môn, thảo luận ca khó và quyết định chuyển tuyến.",en:"Attend clinical supervision, discuss complex cases and decide on referrals."},{time:"17:00",vi:"Tổng hợp số liệu không định danh và chuẩn bị buổi chia sẻ phòng ngừa căng thẳng.",en:"Compile anonymized data and prepare a stress prevention workshop."}],mistakes:{vi:["Chỉ nhìn tổng điểm mà bỏ qua câu 9 của PHQ-9, làm chậm đánh giá an toàn.","Cộng thiếu câu khi chấm thang đo, dẫn tới phân loại mức độ sai.","Chia sẻ ghi chép tham vấn cho nhà trường, doanh nghiệp khi chưa có đồng ý của thân chủ."],en:["Looking only at the total and missing PHQ-9 item 9, delaying the safety assessment.","Leaving out an item when scoring a scale, leading to the wrong severity band.","Sharing session notes with a school or employer without the client's consent."]},career:[{vi:"Cán bộ hỗ trợ tâm lý",en:"Psychological support assistant"},{vi:"Chuyên viên tham vấn tâm lý",en:"Counseling specialist"},{vi:"Chuyên viên tham vấn cao cấp & giám sát chuyên môn",en:"Senior counselor & clinical supervisor"},{vi:"Giám đốc chương trình sức khỏe tinh thần",en:"Director of mental wellbeing programs"}],glossary:[{term:"PHQ-9",vi:"Bảng hỏi sức khỏe bệnh nhân 9 câu dùng sàng lọc và theo dõi mức độ triệu chứng trầm cảm.",en:"A 9-item patient health questionnaire for screening and tracking depressive symptom severity."},{term:"Informed consent",vi:"Đồng thuận có hiểu biết: thân chủ được giải thích mục đích, quy trình, giới hạn bảo mật trước khi đồng ý.",en:"The client agrees after learning the purpose, process and limits of confidentiality."},{term:"Safety plan",vi:"Kế hoạch an toàn do thân chủ và nhà tham vấn cùng xây dựng: dấu hiệu cảnh báo, cách ứng phó và người liên hệ.",en:"A plan built with the client listing warning signs, coping steps and people to contact."},{term:"EAP",vi:"Chương trình hỗ trợ nhân viên do doanh nghiệp tài trợ, cung cấp tham vấn bảo mật cho người lao động.",en:"Employee assistance program funded by employers, offering confidential counseling to staff."},{term:"Referral",vi:"Chuyển tuyến: kết nối thân chủ với dịch vụ chuyên khoa phù hợp khi vượt phạm vi tham vấn.",en:"Connecting the client to a suitable specialist service when needs exceed counseling scope."}],quiz:[{q:{vi:"Điểm PHQ-9 các câu: 1, 2, 1, 2, 2, 1, 1, 0, 0. Tổng điểm thuộc mức nào?",en:"PHQ-9 item scores: 1, 2, 1, 2, 2, 1, 1, 0, 0. Which severity band applies?"},options:{vi:["Nhẹ (5-9)","Trung bình nặng (15-19)","Trung bình (10-14)","Tối thiểu (0-4)"],en:["Mild (5-9)","Moderately severe (15-19)","Moderate (10-14)","Minimal (0-4)"]},answer:2,explain:{vi:"Tổng = 10, thuộc mức trung bình (10-14); câu 9 bằng 0 nên không có tín hiệu nguy cơ từ câu này.",en:"Total = 10, which is moderate (10-14); item 9 is 0, so there is no risk signal from that item."}},{q:{vi:"Doanh nghiệp trả phí EAP yêu cầu xem ghi chép tham vấn của một nhân viên. Bạn làm gì?",en:"The employer paying for the EAP asks to see an employee's session notes. What do you do?"},options:{vi:["Từ chối khi chưa có đồng ý bằng văn bản, chỉ gửi báo cáo tổng hợp không định danh","Gửi ngay vì doanh nghiệp trả phí","Gửi bản tóm tắt bằng lời qua điện thoại","Hỏi đồng nghiệp rồi gửi"],en:["Decline without written consent and send only anonymized aggregate reports","Send them since the employer pays","Summarize them verbally by phone","Ask a colleague, then send"]},answer:0,explain:{vi:"Bảo mật thuộc về thân chủ; bên tài trợ chỉ nhận số liệu tổng hợp theo hợp đồng, trừ khi thân chủ đồng ý.",en:"Confidentiality belongs to the client; sponsors receive only contracted aggregate data unless the client consents."}},{q:{vi:"Tổng PHQ-9 chỉ 7 điểm nhưng câu 9 được chọn mức “vài ngày”. Bước tiếp theo đúng là gì?",en:"The PHQ-9 total is only 7 but item 9 is marked “several days”. What is the right next step?"},options:{vi:["Xếp lịch thường vì tổng điểm thấp","Gửi bài đọc tự giúp và hẹn tháng sau","Bỏ qua vì có thể khách chọn nhầm","Đánh giá an toàn ngay trong ngày, lập kế hoạch an toàn và báo giám sát chuyên môn"],en:["Schedule routinely since the total is low","Send self-help reading and meet next month","Ignore it as a possible mistake","Do a same-day safety assessment, build a safety plan and inform the supervisor"]},answer:3,explain:{vi:"Câu 9 khác 0 là tín hiệu nguy cơ độc lập với tổng điểm, phải đánh giá an toàn kịp thời theo quy trình.",en:"A non-zero item 9 is a risk signal independent of the total and requires a timely safety assessment."}},{q:{vi:"Thân chủ có triệu chứng cần chẩn đoán và cân nhắc dùng thuốc. Nhà tham vấn nên làm gì?",en:"A client shows symptoms needing diagnosis and possible medication. What should the counselor do?"},options:{vi:["Tự chẩn đoán và khuyên dùng thuốc","Chuyển tuyến tới bác sĩ chuyên khoa tâm thần và tiếp tục hỗ trợ phối hợp","Kết thúc tham vấn ngay","Khuyên thân chủ tự mua thuốc"],en:["Diagnose and advise medication yourself","Refer to a psychiatrist and keep providing coordinated support","End counseling immediately","Tell the client to buy medicine"]},answer:1,explain:{vi:"Chẩn đoán và kê đơn vượt phạm vi tham vấn; chuyển tuyến đúng giúp thân chủ được điều trị an toàn.",en:"Diagnosis and prescribing exceed counseling scope; proper referral keeps the client safe."}}],tools_en:["PHQ-9 and GAD-7 screening scales","Encrypted electronic counseling records","Safety plan template","Secure online counseling platform","Informed consent form","Specialist referral directory"]}}})})(window.KKR);
